// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class LmdbNativePackedFtreeCapacityTest {

	@Test
	void incrementalGrowthKeepsValueLanesAllocatedUpToCapacity() {
		int vector = LmdbNativePackedFtree.VECTOR_SIZE;
		LmdbNativePackedFtree.NodeData data = new LmdbNativePackedFtree.NodeData(null);
		// Two doubling steps whose requested lane counts trail the doubled capacity: capacity reaches 4x vector while
		// the packed value blocks only cover 3x vector. The third call must still allocate every lane below capacity.
		data.ensureCapacity(vector + 1);
		data.ensureCapacity(2 * vector + 1);
		data.ensureCapacity(3 * vector + 1);
		data.setValue(3 * vector, 42L);
		assertEquals(42L, data.value(3 * vector));
	}
}
